mapper.select:
SELECT id, user_id, category_id, name, price, original_price, stock,
       status, view_count, condition_level, location, contact_method,
       create_time, update_time, create_by, update_by, del_flag, version,
       MATCH(name) AGAINST(#{c.keyword} IN NATURAL LANGUAGE MODE) AS relevance
FROM eo_product
WHERE MATCH(name) AGAINST(#{c.keyword} IN NATURAL LANGUAGE MODE)
  AND status = #{c.status}
  AND del_flag = 0
  AND price >= #{c.minPrice}
  AND price <= #{c.maxPrice}
  AND condition_level = #{c.conditionLevel}

      AND original_price IS NOT NULL AND original_price > price

ORDER BY relevance DESC, create_time DESC

SELECT product_id, description, create_time, update_time
FROM eo_product_detail
WHERE product_id IN #{id}

SELECT user_id, username, nick_name, avatar
FROM eo_user
WHERE user_id IN #{id}

mapper.update:
UPDATE eo_product
SET search_text = #{searchText}
WHERE id = #{productId}
